def build_beach():
    R = "../"
    qrows = ""
    for k, burn, lvl in [("seestachelbeere", "nie, Rippenquallen haben keine Nesselzellen", "g"), ("ohrenqualle", "kaum spürbar", "g"),
                         ("lungenqualle", "schwach, kann auf empfindlicher Haut jucken", "y"), ("blaue-nesselqualle", "spürbar", "o"),
                         ("kompassqualle", "deutlich, wie Brennnesseln", "o"), ("feuerqualle", "stark, auch abgerissene Tentakel", "r")]:
        qrows += f'<tr><th scope="row"><a href="{R}arten/{k}/index.html">{esc(BY[k]["n"])}</a></th><td><span class="burn burn-{lvl}" aria-hidden="true"></span>{esc(burn)}</td></tr>'
    body = f'''<section class="block page"> <div class="wrap"> <h1>Sicher am Strand</h1> <p class="intro">Die meisten Funde am Strand sind harmlos und schön zum Anschauen. Bei einigen Quallen, bei jungen Robben, bei Bernstein an der Ostsee und im Watt lohnt es sich aber, ein paar Dinge zu wissen.</p> </div> </section>
<section class="block" aria-labelledby="h-q"><div class="wrap"><h2 id="h-q">Welche Quallen brennen?</h2><p class="intro">Auch tote, angespülte Quallen können noch nesseln. Fass im Zweifel keine Qualle an.</p><div class="cmp-wrap"><table class="cmp"><thead><tr><th scope="col">Qualle</th><th scope="col">Brennt sie?</th></tr></thead><tbody>{qrows}</tbody></table></div>
<h3 class="h3 sub-h">Was tun nach Quallenkontakt?</h3><ol class="steps"><li><b>Aus dem Wasser gehen</b> Ruhig bleiben und die Stelle nicht reiben.</li><li><b>Mit Meerwasser abspülen</b> Kein Süßwasser verwenden, es kann weitere Nesselzellen auslösen.</li><li><b>Tentakelreste entfernen</b> Rasierschaum auftragen und trocknen lassen. Dann mit einer Karte oder einem Stöckchen vorsichtig abstreifen, nicht mit bloßen Fingern.</li><li><b>Bei starken Beschwerden Hilfe holen</b> Bei Atemnot, Kreislaufproblemen oder großflächigen Verbrennungen sofort die 112 rufen oder die Badeaufsicht ansprechen.</li></ol></div></section>
<section class="block" aria-labelledby="h-heuler"><div class="wrap"><h2 id="h-heuler">Junge Robbe allein am Strand?</h2><p class="intro">Junge Seehunde, die nach ihrer Mutter rufen, heißen Heuler. Meist ist die Mutter nur auf Jagd und kommt zurück, wenn es ruhig ist.</p><ol class="steps"><li><b>Abstand halten</b> Mindestens 300 Meter Abstand halten und den Weg zum Wasser frei lassen. Auf der Helgoländer Düne gelten mindestens 30 Meter.</li><li><b>Nicht anfassen</b> Robben können beißen. Fasst ein Mensch das Junge an, nimmt die Mutter es oft nicht mehr an.</li><li><b>Weitergehen</b> Hunde anleinen und den Fundort verlassen, damit die Mutter zurückkommen kann. Das Tier muss nicht bewacht werden.</li><li><b>Melden, wenn nötig</b> Wirkt das Tier krank oder bleibt es lange allein: in Schleswig-Holstein die Seehundstation Friedrichskoog (<a href="tel:+4948541372">04854 1372</a>), einen Seehundjäger oder die Polizei, in Niedersachsen die Seehundstation Norddeich (<a href="tel:+494931973330">04931 973330</a>). Fachleute entscheiden, ob es Hilfe braucht.</li></ol></div></section>
<section class="block" aria-labelledby="h-phos"><div class="wrap"><div class="warnbox"><h2 id="h-phos">Bernstein oder Phosphor?</h2><p>An der Ostseeküste, vor allem auf Usedom, werden manchmal Brocken aus weißem Phosphor angespült. Sie stammen aus Brandbomben des Zweiten Weltkriegs und sehen Bernstein sehr ähnlich. Trocknet Phosphor, kann er sich schon ab etwa 20 Grad selbst entzünden und schwere Verbrennungen verursachen.</p><ul><li>Strandfunde nie in die Hosen- oder Jackentasche stecken, sondern in einer Metalldose sammeln.</li><li>Ob ein Fund Bernstein oder Phosphor ist, lässt sich mit bloßem Auge kaum sicher sagen. Nicht reiben, nicht daran riechen, nicht anzünden.</li><li>Bei Verdacht nicht anfassen, Abstand halten und die Polizei verständigen. Hat Phosphor die Haut berührt, die Stelle mit Wasser nass halten oder mit einem feuchten Tuch bedecken und den Notruf 112 wählen.</li></ul></div></div></section>
<section class="block" aria-labelledby="h-watt"><div class="wrap"><h2 id="h-watt">Ebbe, Flut und Watt</h2><ul class="explore tips"><li><div><b>Gezeiten kennen</b><span>Die Flut kommt im Watt schneller, als man denkt, und Priele füllen sich zuerst. Hoch- und Niedrigwasserzeiten veröffentlicht das <a href="https://www.bsh.de/DE/DATEN/Vorhersagen/Gezeiten/gezeiten_node.html" target="_blank" rel="noopener">Bundesamt für Seeschifffahrt und Hydrographie</a>.</span></div></li><li><div><b>Wattwanderung mit Führung</b><span>Längere Strecken, etwa zu Inseln, nur mit zertifizierten Wattführerinnen und Wattführern gehen.</span></div></li><li><div><b>Nationalpark-Regeln</b><span>Im Nationalpark Wattenmeer gibt es Ruhezonen, die nicht betreten werden dürfen. Schilder vor Ort und die <a href="https://www.nationalpark-wattenmeer.de/" target="_blank" rel="noopener">Nationalparkverwaltungen</a> informieren.</span></div></li><li><div><b>Was darf ich mitnehmen?</b><span>Leere Schalen, einzelne Steine und Bernstein (in der Metalldose, siehe oben) sind meist in Ordnung. Lebende Tiere bleiben am Strand, und im Nationalpark gelten die Regeln vor Ort.</span></div></li></ul></div></section>'''
    body += f'<section class="gearband" aria-labelledby="h-gear"><div class="wrap"><div class="head-row"><h2 id="h-gear">Für den Strandtag</h2><a class="gearmore" href="{R}ausruestung/index.html">Alle Empfehlungen ansehen</a></div><ul class="products">{"".join(product(R, g) for g in ("uvlampe", "wattschuhe", "buch", "fernglas"))}</ul>{ADNOTE}</div></section>'
    write("am-strand/index.html", page("am-strand/index.html", "Sicher am Strand", "Welche Quallen brennen, was tun bei einem Heuler und warum Bernstein an der Ostsee in eine Metalldose gehört: Sicherheit am Strand von Nord- und Ostsee.", body, active="am-strand", crumbs=[("Sicher am Strand", "")]))

def build_gear():
    R = "../"
    gsec = lambda t, ks: f'<h2 class="h3 gear-h">{t}</h2><ul class="products">{"".join(product(R, k) for k in ks)}</ul>'
    body = f'''<section class="block page"> <div class="wrap"> <h1>Ausrüstung für die Küste</h1> <p class="intro">Für Seevögel, Robben und Wale brauchst du vor allem ein gutes Fernglas und etwas Geduld. Für Strandfunde reichen offene Augen und ein Gang am Spülsaum nach dem Sturm. Diese Dinge machen beides leichter.</p> {gsec("Vögel, Robben und Wale beobachten", ("fernglas", "vogelbuch", "strandmuschel"))}{gsec("Strandfunde suchen und bestimmen", ("uvlampe", "buch", "becherlupe", "sammelbox"))}{gsec("Watt und Kinder", ("wattschuhe", "kescher", "forscherset"))}{ADNOTE} </div> </section>
<section class="block"><div class="wrap prose"><h2>Welches Fernglas?</h2><p>Für die Küste passt ein Fernglas mit 8- oder 10-facher Vergrößerung und 42 Millimetern Objektiv. Es ist hell genug für trübes Wetter und ruhig genug, um eine Robbe auf der Sandbank aus mehreren hundert Metern zu erkennen. Wasserdicht sollte es sein, denn Gischt und Regen gehören dazu.</p><h2>Mit UV-Licht nach Bernstein suchen</h2><p>Bernstein leuchtet unter ultraviolettem Licht mit 365 Nanometern bläulich bis gelblich. Am besten suchst du in der Dämmerung im frischen Tangsaum nach einem auflandigen Sturm. Leuchte nie in Augen und achte auf Lampen mit Filter, die kaum sichtbares Licht abgeben.</p><h2>Tiere nur kurz anschauen</h2><p>Krebse, Garnelen und Seestachelbeeren kannst du für ein paar Minuten in Meerwasser in einer Becherlupe beobachten. Stelle sie nicht in die Sonne und bringe sie danach genau dorthin zurück, wo du sie gefunden hast.</p></div></section>'''
    write("ausruestung/index.html", page("ausruestung/index.html", "Ausrüstung", "Fernglas und Vogelführer für Seevögel, Robben und Wale, dazu UV-Lampe, Becherlupe und Wattschuhe: Ausrüstung für die Küste an Nord- und Ostsee.", body, active="ausruestung", crumbs=[("Ausrüstung", "")]))

def build_about():
    """Über den Meereskompass: wer die Seite macht, woher die Inhalte stammen, wie sie sich finanziert.
    Wichtig für Vertrauen bei Besuchern und für Google (Erfahrung, Fachwissen, Vertrauenswürdigkeit)."""
    R = "../"
    body = f'''<section class="block page"> <div class="wrap prose"> <h1>Über den Meereskompass</h1>
<p>Der Meereskompass hilft dir, zu erkennen, was du an Nordsee und Ostsee siehst und findest: Seevögel, Robben, Wale und Delfine, dazu Quallen, Muscheln, Schnecken, Krebse, Tang und andere Strandfunde. Er zeigt {counts(SPECIES)} Arten und Funde mit Foto, Merkmalen und Vorkommen und erklärt in {len(PAIRS)} Vergleichen, wie du ähnliche Arten auseinanderhältst.</p>
<h2>Wer den Meereskompass macht</h2>
<p>Den Meereskompass betreibt Nico Schober aus Bremen als privates, unabhängiges Angebot. Texte, Auswahl der Arten und Gestaltung stammen von ihm. Die Seite gehört zu keinem Verband und keinem Hersteller. Die Kontaktdaten stehen im <a href="{R}impressum/index.html">Impressum</a>.</p>
<h2>Woher die Inhalte stammen</h2>
<ul>
<li><b>Steckbriefe:</b> Merkmale, Größen, Lebensweise und Vorkommen sind für Laien zusammengefasst. Zum Nachlesen verlinkt jede Artseite unter „Mehr erfahren“ den passenden Wikipedia-Artikel.</li>
<li><b>Jahreszeiten und Meere:</b> Die Angaben, wann und wo eine Art zu sehen ist, sind grobe Richtwerte für die deutsche Küste. Je nach Ort, Wetter und Jahr weichen sie ab.</li>
<li><b>Fotos und Rufe:</b> von Wikimedia Commons, unter freien Lizenzen, mit Namen der Urheberinnen und Urheber an jedem Bild und jeder Aufnahme.</li>
</ul>
<p>Alle Urheber und Lizenzen stehen gesammelt unter <a href="{R}bildnachweis/index.html">Bildnachweis und Lizenzen</a>.</p>
<h2>Sicherheit geht vor</h2>
<p>Die Hinweise zu Quallen, Heulern, Phosphor und dem Watt ersetzen keine fachliche oder ärztliche Beratung. Bei gestrandeten Tieren hilft die örtliche Seehundstation oder Nationalparkverwaltung, im Notfall die 112. Mehr dazu unter <a href="{R}am-strand/index.html">Sicher am Strand</a>.</p>
<h2>Wie sich die Seite finanziert</h2>
<p>Der Meereskompass ist kostenlos und ohne Anmeldung nutzbar. Einige Seiten empfehlen Ferngläser, Bestimmungsbücher, UV-Lampen oder Wattschuhe mit Werbelinks zu Amazon, die mit * gekennzeichnet sind. Kaufst du über einen solchen Link, erhält der Betreiber eine kleine Provision, für dich ändert sich am Preis nichts. Die Empfehlungen sind nicht selbst getestet, wenn es nicht ausdrücklich dabeisteht, und Hersteller haben keinen Einfluss auf die Auswahl.</p>
<h2>Deine Daten</h2>
<p>Der Meereskompass setzt keine Cookies und misst keine Reichweite. Nur deine Wahl zwischen Nordsee und Ostsee merkt sich dein eigener Browser. Mehr dazu in der <a href="{R}datenschutz/index.html">Datenschutzerklärung</a>.</p>
<h2>Fehler gefunden?</h2>
<p>Wenn dir eine falsche Angabe, ein falsch zugeordnetes Foto oder ein vertauschter Ruf auffällt, schreib gern an <a href="mailto:info@nicoschober.com">info@nicoschober.com</a>. Hinweise werden geprüft und eingearbeitet.</p>
<h2>Schwesterseiten</h2>
<ul>
<li><a href="https://vogelkompass.de/" rel="noopener">Vogelkompass</a>: Vögel in Garten, Park und Feld erkennen</li>
<li><a href="https://waldtierkompass.de/" rel="noopener">Waldtierkompass</a>: Tiere im Wald erkennen</li>
</ul> </div> </section>'''
    about_ld = ld({"@context": "https://schema.org", "@type": "AboutPage", "name": "Über den Meereskompass", "url": DOMAIN + "/ueber/",
                   "inLanguage": "de-DE", "isPartOf": {"@id": WEBSITE_ID}, "mainEntity": {"@id": ORG_ID}})
    write("ueber/index.html", page("ueber/index.html", "Über den Meereskompass: Macher, Quellen, Finanzierung",
          "Wer den Meereskompass macht, woher Fotos, Rufe und Steckbriefe stammen, wie die Seite sich finanziert und wie du Fehler meldest.",
          body, crumbs=[("Über den Meereskompass", "")], seafilter=False, extra_ld=about_ld))

def build_404():
    """Fehlerseite; statichost zeigt sie unter jeder unbekannten Adresse, deshalb Links ab der Wurzel (/)."""
    body = (f'<section class="block page" style="padding-top:clamp(32px,6vw,64px)"> <div class="wrap prose"> <h1>Hier ist nichts angespült</h1> <p>Die Seite, die du suchst, gibt es nicht oder nicht mehr. '
            f'Vielleicht hilft dir die Suche oben weiter, oder einer dieser Wege:</p> <p class="actions"><a class="btn" href="/">Zur Startseite</a>'
            f'<a class="btn ghost" href="/arten/">Alle {len(SPECIES)} Arten und Funde</a><a class="btn ghost" href="/strandjahr/">Küstenjahr</a></p> </div> </section>')
    write("404.html", page("404.html", "Seite nicht gefunden", "Diese Seite gibt es nicht.", body, root="/", noindex=True, seafilter=False))

def build_legal():
    imp = '''<section class="block page"> <div class="wrap prose"> <h1>Impressum</h1> <h2>Angaben gemäß § 5 DDG und § 18 Abs. 1 MStV</h2> <p>Nico Schober<br>Herzogin-Cecilie-Allee 10<br>28217 Bremen<br>Deutschland</p> <h2>Kontakt</h2> <p>E-Mail: <a href="mailto:info@nicoschober.com">info@nicoschober.com</a></p> <h2>Verantwortlich für den Inhalt nach § 18 Abs. 2 MStV</h2> <p>Nico Schober, Anschrift wie oben.</p> <h2>Art des Angebots</h2> <p>Der Meereskompass ist ein privates Informationsangebot. Er verkauft selbst keine Waren oder Dienstleistungen. Einige Seiten enthalten gekennzeichnete Werbelinks zum Amazon-Partnerprogramm; kaufst du über einen solchen Link ein, erhält der Betreiber eine Provision. Als Amazon-Partner verdiene ich an qualifizierten Verkäufen.</p> <h2>Haftung für Inhalte</h2> <p>Die Inhalte wurden mit Sorgfalt erstellt. Für Richtigkeit, Vollständigkeit und Aktualität kann jedoch keine Gewähr übernommen werden. Angaben zu Aktivitätszeiten und Verbreitung sind grobe Richtwerte und können regional abweichen. Die Seite ersetzt keine fachliche oder ärztliche Beratung, etwa nach Quallenkontakt oder bei gestrandeten Tieren. Im Notfall die 112 wählen.</p> <h2>Haftung für Links</h2> <p>Diese Seite enthält Links zu externen Websites, auf deren Inhalte kein Einfluss besteht. Für diese Inhalte ist der jeweilige Anbieter verantwortlich. Zum Zeitpunkt der Verlinkung waren keine Rechtsverstöße erkennbar. Werden Rechtsverletzungen bekannt, wird der betreffende Link umgehend entfernt.</p> <h2>Urheberrecht</h2> <p>Texte und Gestaltung dieser Seite stammen vom Betreiber. Die Fotos stammen von Dritten und stehen unter freien Lizenzen; Urheber und Lizenzen sind aufgeführt unter <a href="../bildnachweis/index.html">Bildnachweis und Lizenzen</a>.</p> </div> </section>'''
    write("impressum/index.html", page("impressum/index.html", "Impressum", "Impressum des Meereskompass.", imp, crumbs=[("Impressum", "")]))
    ds = '''<section class="block page"> <div class="wrap prose"> <h1>Datenschutzerklärung</h1> <p class="stand">Stand: November 2026</p> <h2>1. Verantwortlicher</h2> <p>Verantwortlich für die Datenverarbeitung auf dieser Website ist der im <a href="../impressum/index.html">Impressum</a> genannte Betreiber.</p> <h2>2. Das Wichtigste in Kürze</h2> <ul> <li>Es gibt keine Registrierung, keine Cookies, kein Tracking und keine Reichweitenmessung. Werbung gibt es nur in Form gekennzeichneter Links zu Amazon, die erst beim Anklicken eine Verbindung aufbauen.</li> <li>Die Seite setzt keine Cookies. Wenn du zwischen Nordsee und Ostsee umschaltest, merkt sich dein Browser diese Wahl im lokalen Speicher (siehe Abschnitt 3a).</li> <li>Schriftarten, Fotos, Zeichnungen und Tonaufnahmen werden vom selben Server geladen wie die Seite selbst. Es findet keine Verbindung zu Google Fonts oder anderen Drittanbietern statt.</li> </ul> <h2>3. Hosting und Server-Protokolle</h2> <p>Diese Website wird bei statichost.eu gehostet, einem Dienst von Variable Object Assignment, c/o Knackeriet, Svartmangatan 9, 111 29 Stockholm, Schweden. Die Server stehen nach Angaben des Anbieters in der Europäischen Union; eine Übermittlung in Drittländer findet nicht statt.</p> <p>Beim Aufruf der Seite verarbeitet der Anbieter deine IP-Adresse sowie technisch notwendige Angaben zur Anfrage (abgerufene Datei, Zeitpunkt, Browser), um dir die Seite ausliefern zu können. Nach Angaben des Anbieters wird die IP-Adresse dabei nur für die Dauer der Anfrage im Arbeitsspeicher verarbeitet und nicht protokolliert. Für die Abrechnung werden technische Protokolle ohne personenbezogene Daten (vor allem die übertragene Datenmenge) höchstens sieben Tage aufbewahrt. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; das berechtigte Interesse liegt in der zuverlässigen und sicheren Bereitstellung der Website. statichost.eu ist Auftragsverarbeiter im Sinne von Art. 28 DSGVO; der Anbieter stellt dafür einen eigenen Vertrag zur Auftragsverarbeitung bereit. Weitere Informationen: <a href="https://www.statichost.eu/privacy/" rel="noopener">Datenschutzerklärung von statichost.eu</a>.</p> <h2>3a. Gemerkte Auswahl im Browser</h2> <p>Wählst du oben auf der Seite „Nordsee“ oder „Ostsee“, wird diese Auswahl unter dem Namen <code>sk-sea</code> im lokalen Speicher (localStorage) deines Browsers abgelegt, damit du sie nicht auf jeder Seite neu treffen musst. Der Eintrag enthält nur das gewählte Meer, wird nicht an den Server übertragen und bleibt, bis du „Beide Meere“ wählst oder die Website-Daten in deinem Browser löschst. Rechtsgrundlage ist § 25 Abs. 2 Nr. 2 TDDDG, weil die Speicherung für die von dir ausdrücklich gewünschte Funktion erforderlich ist.</p> <h2>4. Werbelinks zum Amazon-Partnerprogramm</h2> <p>Einige Seiten enthalten mit einem Sternchen gekennzeichnete Links zu Produkten bei Amazon.de. Der Betreiber nimmt am Partnerprogramm von Amazon Europe Core S.à r.l. teil und erhält eine Provision, wenn du über einen solchen Link einkaufst. Auf dieser Website werden dafür keine Skripte, Bilder oder Cookies von Amazon geladen. Erst wenn du einen Werbelink anklickst, wirst du zu Amazon weitergeleitet; Amazon kann dann Cookies setzen, um die Herkunft der Bestellung zuzuordnen. Einzelheiten findest du in der <a href="https://www.amazon.de/gp/help/customer/display.html?nodeId=201909010" target="_blank" rel="noopener">Datenschutzerklärung von Amazon<span class="sr-only"> (öffnet in neuem Fenster)</span></a>.</p> <h2>5. Externe Links</h2> <p>Die Seite verlinkt auf externe Angebote wie Wikipedia, den Vogelkompass oder den Waldtierkompass. Erst wenn du einen solchen Link anklickst, wird eine Verbindung zum jeweiligen Anbieter aufgebaut.</p> <h2>6. Kontakt per E-Mail</h2> <p>Wenn du mir eine E-Mail schreibst, verarbeite ich deine Adresse und den Inhalt der Nachricht, um dir zu antworten. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO. Die Nachricht wird gelöscht, sobald dein Anliegen erledigt ist und keine gesetzlichen Aufbewahrungspflichten entgegenstehen.</p> <h2>7. Deine Rechte</h2> <p>Du hast das Recht auf Auskunft (Art. 15 DSGVO), Berichtigung (Art. 16), Löschung (Art. 17), Einschränkung der Verarbeitung (Art. 18), Datenübertragbarkeit (Art. 20) und Widerspruch (Art. 21). Wende dich dafür an die im Impressum genannte Adresse. Außerdem kannst du dich bei einer Datenschutz-Aufsichtsbehörde beschweren (Art. 77 DSGVO). Für den Betreiber zuständig ist die Landesbeauftragte für Datenschutz und Informationsfreiheit der Freien Hansestadt Bremen.</p> </div> </section>'''
    write("datenschutz/index.html", page("datenschutz/index.html", "Datenschutz", "Datenschutzerklärung des Meereskompass.", ds, crumbs=[("Datenschutz", "")]))
    rows = ""
    for k in sorted(CREDITS, key=lambda x: skey(name_of(x[2:] if x.startswith("x-") else x))):
        a_, lic, url = CREDITS[k]
        n = name_of(k[2:] if k.startswith("x-") else k)
        rows += f'<tr><th scope="row">{esc(n)}</th><td>{esc(a_)}</td><td>{lic_link(lic)}</td><td><a href="{esc(url)}" target="_blank" rel="noopener">Quelle<span class="sr-only"> (öffnet in neuem Fenster)</span></a></td></tr>'
    prows = "".join(f'<tr><th scope="row">{esc(PRODUCTS[k]["name"])}</th><td>{esc(a_)}</td><td>{lic_link(lic)}</td><td><a href="{esc(url)}" target="_blank" rel="noopener">Quelle<span class="sr-only"> (öffnet in neuem Fenster)</span></a></td></tr>' for k, (a_, lic, url) in PHOTO.items())
    srows = ""
    for k in sorted(AUDIO, key=lambda x: skey(name_of(x[2:] if x.startswith("x-") else x))):
        a_, lic, url, sec = AUDIO[k]
        srows += f'<tr><th scope="row">{esc(name_of(k[2:] if k.startswith("x-") else k))}</th><td>{esc(a_)}</td><td>{lic_link(lic)}</td><td><a href="{esc(url)}" target="_blank" rel="noopener">Quelle<span class="sr-only"> (öffnet in neuem Fenster)</span></a></td></tr>'
    sounds = (f'<div class="wrap prose"> <h2>Tonaufnahmen</h2> <p>Die Vogelrufe stammen von Wikimedia Commons und stehen unter den genannten freien Lizenzen oder sind gemeinfrei. Für die Seite wurden sie gekürzt und in MP3 umgewandelt; bearbeitete Aufnahmen unter einer Share-alike-Lizenz (BY-SA) stehen unter derselben Lizenz wie das Original.</p> </div>'
              f'<div class="wrap"><div class="cmp-wrap"><table class="cmp"><thead><tr><td>Vogel</td><th scope="col">Urheber</th><th scope="col">Lizenz</th><th scope="col">Quelle</th></tr></thead><tbody>{srows}</tbody></table></div></div>') if AUDIO else ""
    bn = f'''<section class="block page"> <div class="wrap prose"> <h1>Bildnachweis und Lizenzen</h1> <h2>Fotos</h2> <p>Alle Fotos stammen von Wikimedia Commons und stehen unter den genannten freien Lizenzen. Für die Seite wurden sie verkleinert und zugeschnitten. Die Lizenz ist jeweils mit ihrem Lizenztext verlinkt, die Quelle mit der Originaldatei. Bearbeitete Fotos unter einer Share-alike-Lizenz (BY-SA) stehen unter derselben Lizenz wie das Original.</p> </div> <div class="wrap"><div class="cmp-wrap"><table class="cmp"><thead><tr><td>Fund</td><th scope="col">Urheber</th><th scope="col">Lizenz</th><th scope="col">Quelle</th></tr></thead><tbody>{rows}</tbody></table></div></div> {sounds}<div class="wrap prose"> <h2>Fotos zu den Produktempfehlungen</h2> <p>Die Fotos sind als Beispielfoto gekennzeichnet. Sie zeigen typische Geräte und Beispiele, nicht das verlinkte Produkt. Sichtbare Markenlogos wurden unkenntlich gemacht.</p> </div> <div class="wrap"><div class="cmp-wrap"><table class="cmp"><thead><tr><td>Empfehlung</td><th scope="col">Urheber</th><th scope="col">Lizenz</th><th scope="col">Quelle</th></tr></thead><tbody>{prows}</tbody></table></div></div> <div class="wrap prose"> <h2>Schriften</h2> <p>Outfit (The Outfit Project Authors) und Instrument Sans (Instrument), beide unter der SIL Open Font License 1.1, lokal eingebunden über das Projekt Fontsource.</p> </div> </section>'''
